window.docContents[165].resolve({"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Additional-Exercises--Exercise___-STLC-with-Arithmetic--Preservation":{"contents":"\n\nHint: you will need to define and prove the same helper lemmas we used\nbefore.theorem preservation (t t' : Tm) (T : Ty)\n-- AI\n    (hT : <{ ∅ ⊢ ~t ⦂ ~T }>) (hs : t ⟶ t') : <{ ∅ ⊢ ~t' ⦂ ~T }> := by\n  solution!\n    generalize hΓ : (∅ : Context) = Γ at hT\n    induction hT generalizing t' with\n    | var => cases hs\n    | abs => cases hs\n    | const => cases hs\n    | app Γ T₁ T₂ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      subst hΓ\n      cases hs with\n      | appAbs _ _ _ _ _ =>\n        -- The one interesting case: the desired result is the substitution lemma.\n        cases h₁ with\n        | abs _ _ _ _ _ hb => exact substitution_preserves_typing _ _ _ _ _ _ hb h₂\n      | app1 _ t₁' _ h => exact .app _ _ _ _ _ (ih₁ t₁' h rfl) h₂\n      | app2 _ _ t₂' _ h => exact .app _ _ _ _ _ h₁ (ih₂ t₂' h rfl)\n    | succ Γ t₁ h ih =>\n      subst hΓ\n      cases hs with\n      | succ _ t₁' hst => exact .succ _ _ (ih t₁' hst rfl)\n      | succConst n => exact .const _ _\n    | pred Γ t₁ h ih =>\n      subst hΓ\n      cases hs with\n      | pred _ t₁' hst => exact .pred _ _ (ih t₁' hst rfl)\n      | predConst n => exact .const _ _\n    | mult Γ t₁ t₂ h₁ h₂ ih₁ ih₂ =>\n      subst hΓ\n      cases hs with\n      | multConst _ _ => exact .const _ _\n      | mult1 _ t₁' _ hst => exact .mult _ _ _ (ih₁ t₁' hst rfl) h₂\n      | mult2 _ _ t₂' _ hst => exact .mult _ _ _ h₁ (ih₂ t₂' hst rfl)\n    | ite0 Γ t₁ t₂ t₃ T₀ h₁ h₂ h₃ ih₁ ih₂ ih₃ =>\n      subst hΓ\n      cases hs with\n      | if0Step _ t₁' _ _ hst => exact .ite0 _ _ _ _ _ (ih₁ t₁' hst rfl) h₂ h₃\n      | if0Zero => exact h₂\n      | if0Nonzero => exact h₃\n\n\n","context":"Type Systems\u0009StlcProp: Properties of STLC\u0009Additional Exercises\u0009Exercise: STLC with Arithmetic","header":"6.7.1.2. Preservation","id":"/StlcProp/#Type-Systems--StlcProp___-Properties-of-STLC--Additional-Exercises--Exercise___-STLC-with-Arithmetic--Preservation"}});